def _paint(text: str, key: str, *, enabled: bool) -> str:
    if not enabled:
        return text
    codes = (
        _SGR_CODES
        if os.environ.get("COLORTERM") in {"truecolor", "24bit"}
        else _ANSI_CODES
    )
    return f"\033[{codes[key]}m{text}\033[0m"


