def _publication_error(
    *,
    kind: str,
    version: str,
    origin: str,
    detail: str,
) -> InstallError:
    safe_origin = _safe_url(origin)
    safe_detail = _sanitize_diagnostic(detail)
    if kind == "unpublished":
        return InstallError(
            "installer_release_unpublished: "
            f"Yoke {version} is not published at {safe_origin} ({safe_detail}); "
            f"publish Yoke {version} at {safe_origin}, or correct the requested "
            "version, then rerun the installer"
        )
    return InstallError(
        "installer_release_unverified: "
        f"could not confirm Yoke {version} is published at {safe_origin} "
        f"({safe_detail}); restore access to {safe_origin} and rerun the installer"
    )


def _iter_exceptions(exc: BaseException):
    seen: set[int] = set()
    stack = [exc]
    while stack:
        current = stack.pop()
        if current is None or id(current) in seen:
            continue
        seen.add(id(current))
        yield current
        cause = current.__cause__
        if isinstance(cause, BaseException):
            stack.append(cause)
        reason = getattr(current, "reason", None)
        if isinstance(reason, BaseException):
            stack.append(reason)


def _publication_fetch_error(
    version: str, origin: str, exc: BaseException
) -> InstallError:
    for item in _iter_exceptions(exc):
        if isinstance(item, urllib.error.HTTPError):
            kind = "unpublished" if item.code in {404, 410} else "unverified"
            return _publication_error(
                kind=kind,
                version=version,
                origin=origin,
                detail=f"HTTP {item.code}",
            )
    for item in _iter_exceptions(exc):
        if "SSL" in type(item).__name__:
            return _publication_error(
                kind="unverified",
                version=version,
                origin=origin,
                detail="TLS error",
            )
    return _publication_error(
        kind="unverified",
        version=version,
        origin=origin,
        detail=_sanitize_diagnostic(str(exc)),
    )


def _format_command_failure(
    command: Sequence[str],
    result: subprocess.CompletedProcess[str],
) -> str:
    safe_command = _bounded_diagnostic(" ".join(command), DIAGNOSTIC_MAX_CHARS)
    safe_stdout = _bounded_diagnostic(result.stdout or "", DIAGNOSTIC_MAX_CHARS)
    safe_stderr = _bounded_diagnostic(result.stderr or "", DIAGNOSTIC_MAX_CHARS)
    return (
        "Yoke dependency resolution uses the configured Yoke package index "
        f"and public PyPI ({PYPI_INDEX_URL}).\n"
        f"command failed with {result.returncode}: {safe_command}\n"
        f"stdout:\n{safe_stdout}\n"
        f"stderr:\n{safe_stderr}"
    )


def _bounded_diagnostic(value: str, limit: int) -> str:
    safe = _sanitize_diagnostic(value)
    if len(safe) <= limit:
        return safe
    return f"<earlier output omitted>\n{safe[-limit:]}"


def _sanitize_diagnostic(value: str) -> str:
    """Remove URL credentials/query material from operator-visible text."""

    return _URL_RE.sub(lambda match: _safe_url(match.group(0)), value)


def _safe_url(value: str) -> str:
    raw = str(value or "")
    try:
        parsed = urllib.parse.urlsplit(raw)
    except ValueError:
        return "<redacted-url>"
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname:
        return raw
    host = parsed.hostname
    if ":" in host and not host.startswith("["):
        host = f"[{host}]"
    try:
        port = parsed.port
    except ValueError:
        port = None
    netloc = f"{host}:{port}" if port is not None else host
    return urllib.parse.urlunsplit((parsed.scheme, netloc, parsed.path, "", ""))


def _env_truthy(name: str) -> bool:
    return os.environ.get(name, "").lower() in {"1", "true", "yes", "y"}


def product_spec(version: str | None) -> str:
    if version:
        return f"{PRODUCT_PACKAGE}=={version}"
    return PRODUCT_PACKAGE


def _rerun_command(base_url: str, *, channel: str | None = None) -> str:
    origin = _safe_url(base_url).rstrip("/")
    if origin == DEFAULT_BASE_URL:
        scheme, host = origin.split("://", 1)
        api_prefix = "api."
        if host.startswith(api_prefix):
            host = host[len(api_prefix) :]
        origin = f"{scheme}://{host}"
    command = f"curl -fsSL {origin}/install | sh"
    if channel is not None:
        command += f" -s -- --channel {shlex.quote(channel)}"
    return command


def _product_spec_version(spec: str) -> str | None:
    prefix = f"{PRODUCT_PACKAGE}=="
    if spec.startswith(prefix):
        version = spec[len(prefix) :].strip()
        return version or None
    return None


def _with_product_requirements(version: str | None) -> tuple[str, ...]:
    args: list[str] = []
    for package in LOCKSTEP_PRODUCT_PACKAGES:
        requirement = f"{package}=={version}" if version else package
        args.extend(["--with", requirement])
    return tuple(args)


def _verify_product_package_versions(
    runtime: object,
    expected_version: str,
) -> None:
    missing_versions = (
        "product-boundary audit failed: `yoke status --json` did not "
        "report runtime package versions."
    )
    if not isinstance(runtime, dict):
        raise InstallError(missing_versions)
    raw_versions = runtime.get("package_versions")
    if not isinstance(raw_versions, dict):
        raise InstallError(missing_versions)
    expected_packages = (PRODUCT_PACKAGE, *LOCKSTEP_PRODUCT_PACKAGES)
    mismatched = [
        f"{package}={raw_versions.get(package) or '<missing>'}"
        for package in expected_packages
        if raw_versions.get(package) != expected_version
    ]
    if mismatched:
        raise InstallError(
            "product-boundary audit failed: installed Yoke package versions "
            f"do not match channel version {expected_version}: " + ", ".join(mismatched)
        )


def _verify_product_package_presence(runtime: object) -> None:
    """Require every package needed by installed hooks and product commands."""
    if not isinstance(runtime, dict):
        raise InstallError(
            "product-boundary audit failed: `yoke status --json` did not "
            "report runtime package versions."
        )
    raw_versions = runtime.get("package_versions")
    if not isinstance(raw_versions, dict):
        raise InstallError(
            "product-boundary audit failed: `yoke status --json` did not "
            "report runtime package versions."
        )
    missing = [
        package
        for package in (PRODUCT_PACKAGE, *LOCKSTEP_PRODUCT_PACKAGES)
        if not raw_versions.get(package)
    ]
    if missing:
        raise InstallError(
            "product-boundary audit failed: installed Yoke product packages "
            "are incomplete: " + ", ".join(missing)
        )


def _display_version(raw: str) -> str:
    raw = (raw or "").strip()
    if not raw:
        return ""
    match = _DEV_VERSION_RE.match(raw)
    if not match:
        return raw
    return f"{match.group('base')} (dev {match.group('local')})"


def _uv_reported_already_installed(
    result: subprocess.CompletedProcess[str],
) -> bool:
    blob = f"{result.stdout}\n{result.stderr}".lower()
    return any(
        text in blob
        for text in (
            "already installed",
            "nothing to do",
            "is up to date",
        )
    )


def _failure_reason(result: subprocess.CompletedProcess[str]) -> str:
    for stream in (result.stderr, result.stdout):
        lines = [line.strip() for line in (stream or "").splitlines() if line.strip()]
        if lines:
            return _bounded_diagnostic(lines[-1], FAILURE_REASON_MAX_CHARS)
    return f"uv exited with status {result.returncode}."


def _release_records_url(base_url: str, version: str) -> str:
    quoted = urllib.parse.quote(version, safe="")
    return (
        f"{base_url.rstrip('/')}/{_RELEASE_RECORD_DIR}/{quoted}/"
        f"{_RELEASE_RECORD_FILENAME}"
    )


def fetch_url(url: str) -> bytes:
    try:
        with urllib.request.urlopen(url, timeout=60) as response:
            return response.read()
    except urllib.error.URLError as exc:
        raise InstallError(
            f"could not fetch {_safe_url(url)}: {_sanitize_diagnostic(str(exc))}"
        ) from exc
    except OSError as exc:
        raise InstallError(
            f"could not fetch {_safe_url(url)}: {_sanitize_diagnostic(str(exc))}"
        ) from exc


def _install_candidate(
    command: list[str], env: dict[str, str], root: Path, generation: Path, version: str
):
    """uv owns each private tool environment; only publication changes PATH."""
    isolated = dict(
        env,
        UV_TOOL_DIR=str(generation / "tools"),
        UV_TOOL_BIN_DIR=str(generation / "bin"),
    )
    try:
        result = _install_qualified_candidate(command, isolated, generation)
    except InstallError:
        shutil.rmtree(generation)
        raise
    if result.returncode:
        shutil.rmtree(generation)
        return result
    bin_dir = subprocess.run(
        ["uv", "tool", "dir", "--bin"],
        env=env,
        capture_output=True,
        text=True,
        check=True,
    ).stdout.strip()
    if not Path(bin_dir).is_absolute():
        raise InstallError(
            "cli_launcher_directory_unavailable: repair uv tool dir --bin and retry"
        )
    python = generation / "tools" / "yoke-cli" / "bin" / "python3"
    runtime_script = generation / "runtime.py"
    runtime_script.write_text(CLI_RUNTIME_SOURCE, encoding="utf-8")
    activation = subprocess.run(
        [
            str(python),
            "-I",
            str(runtime_script),
            str(root),
            str(generation),
            bin_dir,
            version,
        ],
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    return subprocess.CompletedProcess(
        command,
        activation.returncode,
        result.stdout + activation.stdout,
        result.stderr + activation.stderr,
    )


def _run_isolated_install(command: list[str], env: dict[str, str]):
    location = subprocess.run(
        ["uv", "tool", "dir"],
        env=env,
        capture_output=True,
        text=True,
        check=True,
    ).stdout.strip()
    root = Path(location) / "yoke-cli-releases"
    if not Path(location).is_absolute():
        raise InstallError(
            "cli_release_root_unavailable: uv returned no absolute tool directory; repair uv and retry"
        )
    releases = root / "releases"
    releases.mkdir(parents=True, exist_ok=True)
    version = _product_spec_version(command[3])
    if not version or not re.fullmatch(r"[A-Za-z0-9_.+-]+", version):
        raise InstallError(
            "cli_release_version_required: select an exact published release and retry"
        )
    staging = Path(tempfile.mkdtemp(prefix=f"{version}-", dir=root))
    lease = (staging / "lease").open("a+")
    fcntl.flock(lease, fcntl.LOCK_SH)
    (staging / "pending").touch()
    generation = releases / staging.name
    staging.rename(generation)
    with lease:
        try:
            result = _install_candidate(command, env, root, generation, version)
        except (OSError, subprocess.SubprocessError) as exc:
            raise InstallError(
                f"cli_release_install_failed: {exc}; repair uv and rerun the installer"
            ) from exc
        return result


def run_command_capture(command: Sequence[str]) -> subprocess.CompletedProcess[str]:
    env = {
        key: value
        for key, value in os.environ.items()
        if key not in RESOLVER_SOURCE_ENV_VARS
    }
    if list(command)[:3] == ["uv", "tool", "install"]:
        try:
            return _run_isolated_install(list(command), env)
        except (OSError, subprocess.SubprocessError) as exc:
            raise InstallError(
                f"cli_release_install_failed: {exc}; repair uv and rerun the installer"
            ) from exc
    return subprocess.run(
        list(command),
        check=False,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )


def _unexpected_status_error_codes(status: object) -> list[str]:
    if not isinstance(status, dict):
        return ["status_not_object"]
    issues = status.get("issues")
    if not isinstance(issues, list):
        return ["issues_missing"]
    unexpected: list[str] = []
    for issue in issues:
        if not isinstance(issue, dict):
            unexpected.append("issue_not_object")
            continue
        severity = str(issue.get("severity") or "")
        code = str(issue.get("code") or "")
        if severity == "error" and code not in FRESH_STATUS_ERROR_CODES:
            unexpected.append(code or "missing_code")
    return unexpected


def _loads_json(data: bytes, label: str) -> dict[str, object]:
    try:
        value = json.loads(data.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InstallError(f"{label} is not valid JSON") from exc
    if not isinstance(value, dict):
        raise InstallError(f"{label} must be a JSON object")
    return value


def _require_channel_release_evidence(
    channel: dict[str, object],
    label: str,
) -> None:
    """Preserve historical v2 while requiring content evidence from v3."""
    schema_version = channel.get("schema_version")
    if schema_version == 2:
        return
    if schema_version != 3:
        raise InstallError(f"{label} channel has unsupported schema_version")
    migration_history = channel.get("migration_history")
    if not isinstance(migration_history, dict):
        raise InstallError(
            f"{label} channel schema v3 is missing trusted migration history evidence"
        )
    digest = str(migration_history.get("manifest_sha256") or "")
    source_commit = str(migration_history.get("source_commit") or "")
    manifest_url = str(migration_history.get("manifest_url") or "")
    evidence_url = str(migration_history.get("evidence_url") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise InstallError(f"{label} channel has an invalid migration manifest digest")
    if not re.fullmatch(r"[0-9a-f]{40}", source_commit):
        raise InstallError(f"{label} channel has an invalid migration source commit")
    if not manifest_url.endswith("/migration-history.json"):
        raise InstallError(f"{label} channel has an invalid migration manifest URL")
    if not evidence_url.endswith("/migration-history-record.json"):
        raise InstallError(
            f"{label} channel has an invalid migration release-evidence URL"
        )


# uv children create files with this umask, so fresh cache entries and tool
# environments are never group- or other-writable. The parent umask is unchanged.
CANDIDATE_UMASK = 0o022
# These two distributions own every credential-helper bundle source.
HELPER_SOURCE_PACKAGES = ("yoke-cli", "yoke-contracts")
# Runs inside the candidate: the release's own helper-bundle owner enumerates
# and safe-reads every source the credential helper copies, plus the launcher.
HELPER_SOURCE_CHECK = """
import json, os, stat
from pathlib import Path
from yoke_cli.config import github_git_credential_bundle as bundle
from yoke_cli.config import github_git_credential_launcher as launcher
paths = [source for source, _name in bundle._bundle_sources()]
paths.append(Path(launcher.__file__))
loose, refusal = [], None
for path in paths:
    try:
        bundle._safe_read_source(path)
    except bundle.GitHubCredentialBundleError as exc:
        info = os.lstat(path) if os.path.lexists(path) else None
        mode = stat.S_IMODE(info.st_mode) if info else 0
        if (
            info
            and stat.S_ISREG(info.st_mode)
            and info.st_size <= bundle.MAX_HELPER_SOURCE_BYTES
            and mode & 0o022
        ):
            loose.append(f"{path} (mode {mode:04o})")
        elif refusal is None:
            refusal = f"{path}: {exc}"
print(json.dumps({"checked": len(paths), "unsafe_permissions": loose, "refusal": refusal}))
"""


def _run_candidate_uv(command: list[str], env: dict[str, str]):
    return subprocess.run(
        command,
        env=env,
        capture_output=True,
        text=True,
        check=False,
        umask=CANDIDATE_UMASK,
    )


def _unsafe_helper_source_permissions(
    generation: Path, env: dict[str, str]
) -> list[str]:
    """Return helper sources unsafe only by permissions; refuse anything else."""
    python = generation / "tools" / "yoke-cli" / "bin" / "python3"
    try:
        result = subprocess.run(
            [str(python), "-I", "-c", HELPER_SOURCE_CHECK],
            env=env,
            capture_output=True,
            text=True,
            check=False,
            timeout=120,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise InstallError(
            f"helper_source_check_failed: the candidate could not check its "
            f"credential-helper sources: {exc}; rerun the installer."
        ) from exc
    lines = result.stdout.strip().splitlines()
    try:
        verdict = json.loads(lines[-1]) if lines else None
    except ValueError:
        verdict = None
    if result.returncode or not isinstance(verdict, dict):
        raise InstallError(
            "helper_source_check_failed: the candidate could not check its "
            "credential-helper sources: "
            + _bounded_diagnostic(result.stderr or result.stdout, DIAGNOSTIC_MAX_CHARS)
            + "; rerun the installer."
        )
    if verdict.get("refusal"):
        raise InstallError(
            "helper_source_unsafe: a credential-helper source is not a safe regular "
            f"file: {verdict['refusal']}; repair or remove it, then rerun the installer."
        )
    return [str(path) for path in verdict.get("unsafe_permissions") or []]


def _install_qualified_candidate(
    command: list[str], env: dict[str, str], generation: Path
):
    """Install the candidate; repair unsafe cached helper sources at most once."""
    result = _run_candidate_uv(command, env)
    if result.returncode:
        return result
    loose = _unsafe_helper_source_permissions(generation, env)
    if not loose:
        return result
    # Evict only the helper-owning packages from the cache uv just used.
    config = (
        command[command.index("--config-file") :][:2]
        if "--config-file" in command
        else []
    )
    clean = subprocess.run(
        ["uv", "cache", "clean", *HELPER_SOURCE_PACKAGES, *config],
        env=env,
        capture_output=True,
        text=True,
        check=False,
        umask=CANDIDATE_UMASK,
    )
    if clean.returncode:
        raise InstallError(
            "helper_source_cache_clean_failed: uv cache clean "
            + " ".join(HELPER_SOURCE_PACKAGES)
            + " failed after group- or other-writable helper sources were found ("
            + ", ".join(loose)
            + "): "
            + _bounded_diagnostic(clean.stderr or clean.stdout, DIAGNOSTIC_MAX_CHARS)
            + "; let other uv commands finish, then rerun the installer."
        )
    print(
        "helper_source_cache_repaired: evicted uv cache entries for "
        + ", ".join(HELPER_SOURCE_PACKAGES)
        + " because helper sources were group- or other-writable ("
        + ", ".join(loose)
        + "); reinstalling once.",
        file=sys.stderr,
    )
    retry = _run_candidate_uv(command, env)
    if retry.returncode:
        return retry
    still = _unsafe_helper_source_permissions(generation, env)
    if still:
        raise InstallError(
            "helper_source_permissions_unsafe: helper sources are still group- or "
            "other-writable after one targeted uv cache clean and reinstall ("
            + ", ".join(still)
            + "). Another process may be writing the uv cache "
            "with a permissive umask; stop it or set UV_CACHE_DIR to a private "
            "cache, then rerun the installer."
        )
    return subprocess.CompletedProcess(
        command,
        0,
        result.stdout + clean.stdout + retry.stdout,
        result.stderr + clean.stderr + retry.stderr,
    )


class InstallerVerification:
    def _resolve_installed_yoke_bin(self) -> str:
        seen: set[str] = set()
        for candidate in self._installed_yoke_candidates():
            if candidate in seen:
                continue
            seen.add(candidate)
            if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
                return candidate
        found = self.which("yoke")
        if found:
            return found
        raise InstallError("yoke command not found after install")

    def _installed_yoke_candidates(self) -> Iterable[str]:
        uv_tool_bin = os.environ.get("UV_TOOL_BIN_DIR")
        if uv_tool_bin:
            yield os.path.join(uv_tool_bin, "yoke")
        xdg_bin = os.environ.get("XDG_BIN_HOME")
        if xdg_bin:
            yield os.path.join(xdg_bin, "yoke")
        uv_bin = self.capture_runner(["uv", "tool", "dir", "--bin"])
        if uv_bin.returncode == 0:
            directory = uv_bin.stdout.strip()
            if directory and "\n" not in directory and os.path.isabs(directory):
                yield os.path.join(directory, "yoke")
        home = os.path.expanduser("~")
        if home and home != "~":
            yield os.path.join(home, ".local", "bin", "yoke")

    def _smoke_yoke(self, yoke_bin: str = "yoke") -> str:
        version = ""
        for argv in (
            [yoke_bin, "--version"],
            [yoke_bin, "--help"],
        ):
            result = self.capture_runner(argv)
            if result.returncode != 0:
                raise InstallError(_format_command_failure(argv, result))
            if argv[1:] == ["--version"]:
                version = result.stdout.strip()
        return version

    def _product_boundary_audit(
        self,
        *,
        expected_version: str | None = None,
        yoke_bin: str = "yoke",
    ) -> None:
        source_dev_authority = "source-dev/admin"
        argv = [yoke_bin, "status", "--json"]
        result = self.capture_runner(argv)
        try:
            status = json.loads(result.stdout)
        except json.JSONDecodeError as exc:
            raise InstallError(
                "product-boundary audit failed: `yoke status --json` did not "
                f"return valid JSON ({exc})."
            ) from exc
        if result.returncode != 0:
            unexpected = _unexpected_status_error_codes(status)
            if unexpected:
                raise InstallError(
                    "product-boundary audit failed: `yoke status --json` "
                    "reported unexpected errors on a fresh install: "
                    + ", ".join(unexpected)
                )
        connection = status.get("connection") if isinstance(status, dict) else None
        authority = ""
        if isinstance(connection, dict):
            authority = str(connection.get("client_authority") or "")
        if authority == source_dev_authority:
            raise InstallError(
                "product-boundary audit failed: yoke reports client authority "
                f"{authority!r}; a product install must use the product API, not "
                "source-dev/admin authority."
            )
        # The engine (yoke-core) is installed on every machine by design; the
        # audit verifies it stays inert — the client must hold product-API
        # authority, never local source-dev/admin authority. Reject a reported
        # authority violation before diagnosing package completeness so the
        # security boundary remains the primary failure.
        runtime = status.get("runtime") if isinstance(status, dict) else None
        _verify_product_package_presence(runtime)
        if expected_version:
            _verify_product_package_versions(runtime, expected_version)

    def _repair_credential_helper(self, yoke_bin: str) -> None:
        """Point registered checkouts at the active immutable helper bundle."""
        argv = [yoke_bin, "github", "credential-helper", "refresh", "--json"]
        result = self.capture_runner(argv)
        if result.returncode != 0:
            raise InstallError(_format_command_failure(argv, result))
        diagnostic = (result.stderr or result.stdout or "").strip()[-2048:]
        try:
            payload = json.loads(result.stdout)
        except (ValueError, TypeError):
            payload = None
        if not isinstance(payload, dict) or "configured" not in payload:
            raise InstallError(
                "credential helper repair produced no result: "
                f"{diagnostic or 'no diagnostic output'}"
            )
        error = payload.get("error")
        if error:
            raise InstallError(f"credential helper repair failed: {error}")
        if payload.get("repaired"):
            print(
                self._say("Rebuilt the git credential helper bundle for this release."),
                file=self.stdout,
            )

    def _restart_running_dashboard(self, yoke_bin: str) -> None:
        argv = [yoke_bin, "ui", "restart-running", "--json"]
        try:
            result = self.capture_runner(argv)
        except OSError as exc:
            raise InstallError(
                f"ui_restart_unavailable: {exc}; rerun the installer to repair Yoke."
            ) from exc
        if result.returncode:
            raise InstallError(
                "ui_restart_failed: "
                + _format_command_failure(argv, result)
                + "; recover with `yoke ui down` and `yoke ui up --no-browser`, "
                "then rerun the installer."
            )
        try:
            payload = json.loads(result.stdout)
        except (ValueError, TypeError):
            payload = None
        if (
            not isinstance(payload, dict)
            or payload.get("ok") is not True
            or type(payload.get("restarted")) is not bool
        ):
            raise InstallError(
                "ui_restart_result_invalid: dashboard restart returned no valid receipt; "
                "rerun the installer to repair the installed Yoke executable."
            )
        if payload["restarted"]:
            print(
                self._say(
                    "Restarted the running dashboard with the installed Yoke version."
                ),
                file=self.stdout,
            )

    def _record_distribution(self, yoke_bin: str) -> None:
        argv = [
            yoke_bin,
            "settings",
            "set",
            "distribution",
            json.dumps(
                {"origin": self.options.base_url, "channel": self.options.channel}
            ),
        ]
        result = self.capture_runner(argv)
        if result.returncode != 0:
            raise InstallError(
                "distribution_record_failed: " + _format_command_failure(argv, result)
            )

    def _advise_path(self, yoke_bin: str) -> None:
        # The shim prepends the tool bin dir to the installer's own PATH, so
        # only the PATH the user's shell handed over shows whether it can run yoke.
        inherited = os.environ.get(
            "YOKE_INSTALL_INHERITED_PATH", os.environ.get("PATH", "")
        )
        if os.path.dirname(yoke_bin) in inherited.split(os.pathsep):
            return
        print(
            self._say("Open a new terminal to use Yoke. If it is still missing, run:"),
            file=self.stdout,
        )
        print(self._say("yoke path fix --yes"), file=self.stdout)


class InstallerResolution:
    def install_command(
        self, spec: str, *, config_path: str | None = None
    ) -> list[str]:
        command = [
            "uv",
            "tool",
            "install",
            spec,
            "--python",
            PYTHON_CONSTRAINT,
            "--reinstall",
            "--force",
            *_with_product_requirements(_product_spec_version(spec)),
            "--default-index",
            PYPI_INDEX_URL,
            "--index-strategy",
            INDEX_STRATEGY,
        ]
        if config_path is not None:
            command.extend(["--config-file", config_path])
        return command

    def _write_uv_index_config(self) -> str:
        with tempfile.NamedTemporaryFile(
            "w",
            encoding="utf-8",
            prefix="yoke-uv-index-",
            suffix=".toml",
            delete=False,
        ) as file:
            file.write(self._uv_index_config_text())
            return file.name

    def _uv_index_config_text(self) -> str:
        return (
            "[[index]]\n"
            'name = "yoke-private"\n'
            f'url = "{self.index_url}"\n'
            "ignore-error-codes = [403]\n"
        )

    def _resolve_version(self) -> str | None:
        if self.options.version:
            return self.options.version
        channel_url = (
            f"{self.options.base_url}/dist/channels/{self.options.channel}.json"
        )
        try:
            channel_bytes = self.fetcher(channel_url)
        except InstallError as exc:
            if (
                self.options.channel != DEFAULT_CHANNEL
                and self.options.base_url == DEFAULT_BASE_URL
            ):
                raise InstallError(
                    f"{exc}. This installer origin publishes the "
                    f"{DEFAULT_CHANNEL} channel, not {self.options.channel}"
                ) from exc
            raise
        channel = _loads_json(channel_bytes, f"{self.options.channel} channel")
        version = channel.get("version")
        if not isinstance(version, str) or not version:
            raise InstallError(
                f"{self.options.channel} channel is missing a version pin"
            )
        _require_channel_release_evidence(channel, self.options.channel)
        return version

    def _require_published_release(self, version: str | None) -> None:
        """Refuse a dry-run whose exact version is not published at this origin."""
        origin = _safe_url(self.options.base_url)
        if not version:
            raise InstallError(
                "installer_release_unpublished: dry-run resolved no Yoke version "
                f"at {origin}; pass --version or a channel that names a published "
                "release, then rerun the installer"
            )
        url = _release_records_url(self.options.base_url, version)
        try:
            payload_bytes = self.fetcher(url)
        except InstallError as exc:
            raise _publication_fetch_error(version, origin, exc) from None
        except (urllib.error.URLError, OSError, TimeoutError) as exc:
            raise _publication_fetch_error(version, origin, exc) from None
        try:
            payload = json.loads(payload_bytes.decode("utf-8"))
        except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise _publication_error(
                kind="unverified",
                version=version,
                origin=origin,
                detail=f"release record is not valid JSON ({exc})",
            ) from None
        if not isinstance(payload, list):
            raise _publication_error(
                kind="unverified",
                version=version,
                origin=origin,
                detail="release record is not a JSON list",
            )
        if not payload:
            raise _publication_error(
                kind="unpublished",
                version=version,
                origin=origin,
                detail="release record lists no published wheels",
            )

    def _run_uv_install(self, command: Sequence[str]) -> bool:
        result = self.capture_runner(list(command))
        if result.returncode != 0:
            probe = self.capture_runner(
                ["uv", "python", "find", "--no-python-downloads", PYTHON_CONSTRAINT]
            )
            if probe.returncode != 0:
                raise InstallError(
                    f"supported_python_unavailable: Yoke supports Python {PYTHON_CONSTRAINT}. "
                    "Automatic managed-Python download failed or is disabled. "
                    "Check network access and uv's Python download settings, or run "
                    f"uv python install {shlex.quote(PYTHON_CONSTRAINT)}, then rerun "
                    "the installer or yoke update. " + _failure_reason(result)
                )
            print(self._say("Install failed"), file=self.stdout)
            print(
                _paint("✗ Couldn't install Yoke.", "danger", enabled=self.color),
                file=self.stdout,
            )
            reason = _paint(_failure_reason(result), "dim", enabled=self.color)
            print(f"  {reason}", file=self.stdout)
            print("Try again:", file=self.stdout)
            retry = _paint(
                _rerun_command(self.options.base_url), "bright", enabled=self.color
            )
            print(f"  {retry}", file=self.stdout, flush=True)
            raise InstallError(_format_command_failure(command, result))
        return _uv_reported_already_installed(result)

    def _print_resolution_failure(self, exc: InstallError) -> None:
        print(self._say("Install failed"), file=self.stdout)
        print(
            _paint(
                "✗ Couldn't find a Yoke release to install.",
                "danger",
                enabled=self.color,
            ),
            file=self.stdout,
        )
        print(
            f"  {_paint(_sanitize_diagnostic(str(exc)), 'dim', enabled=self.color)}",
            file=self.stdout,
        )
        print("Try again:", file=self.stdout)
        retry_channel = (
            DEFAULT_CHANNEL
            if self.options.base_url == DEFAULT_BASE_URL
            and self.options.channel != DEFAULT_CHANNEL
            else None
        )
        retry = _paint(
            _rerun_command(self.options.base_url, channel=retry_channel),
            "bright",
            enabled=self.color,
        )
        print(f"  {retry}", file=self.stdout, flush=True)


class Installer(InstallerVerification, InstallerResolution):
    def __init__(
        self,
        options: InstallOptions,
        *,
        fetcher=None,
        runner=None,
        which=None,
        stdout=None,
        color=None,
    ) -> None:
        self.options = options
        self.fetcher = fetcher or fetch_url
        self.capture_runner = runner or run_command_capture
        self.terminal_runner = runner or subprocess.run
        self.which = which or shutil.which
        self.stdout = stdout or sys.stdout
        self.color = self._resolve_color(self.stdout) if color is None else color
        self.plain_glyphs = self._resolve_plain_glyphs()

    @staticmethod
    def _resolve_color(stream) -> bool:
        # The shim hands down its own color decision via YOKE_INSTALL_FORCE_COLOR
        # so the setup log matches the welcome banner exactly; absent that we fall
        # back to the usual NO_COLOR / tty / TERM gating.
        force = os.environ.get("YOKE_INSTALL_FORCE_COLOR")
        if force == "1":
            return True
        if force == "0":
            return False
        if os.environ.get("NO_COLOR") is not None:
            return False
        isatty = getattr(stream, "isatty", None)
        if not callable(isatty) or not isatty():
            return False
        term = os.environ.get("TERM", "")
        return bool(term) and term != "dumb"

    @staticmethod
    def _resolve_plain_glyphs() -> bool:
        force = os.environ.get("YOKE_INSTALL_FORCE_PLAIN")
        if force == "1":
            return True
        if force == "0":
            return False
        term = os.environ.get("TERM", "")
        return (
            term.startswith("screen") or term == "dumb" or bool(os.environ.get("STY"))
        )

    @staticmethod
    def _gutter(stream) -> str:
        if Installer._resolve_plain_glyphs():
            return PLAIN_GUTTER_ICON
        return _paint(GUTTER, "amber", enabled=Installer._resolve_color(stream))

    def _say(self, message: str) -> str:
        """One branded gutter line, plain in screen/dumb terminals."""
        if self.plain_glyphs:
            return f"{PLAIN_GUTTER_ICON} {message}"
        return f"{_paint(GUTTER, 'amber', enabled=self.color)} {message}"

    @property
    def index_url(self) -> str:
        return f"{self.options.base_url}/simple/"

    def run(self) -> None:
        libc = (
            platform.libc_ver()[0].lower() if sys.platform.startswith("linux") else ""
        )
        if sys.platform.startswith("linux") and (
            libc == "musl" or (libc != "glibc" and glob.glob("/lib/ld-musl-*.so.1"))
        ):
            raise InstallError(
                "unsupported_libc: musl Linux (including Alpine) is unsupported. "
                "Use glibc Linux, such as Ubuntu, Debian, or Fedora, "
                "then rerun the installer."
            )
        try:
            version = self._resolve_version()
        except InstallError as exc:
            self._print_resolution_failure(exc)
            raise
        spec = product_spec(version)
        if self.options.dry_run:
            self._require_published_release(version)
            command = self.install_command(spec, config_path="<temporary uv config>")
            print(f"Resolved Yoke {version}", file=self.stdout)
            isolated = [
                "env",
                "UV_TOOL_DIR=<new private release>/tools",
                "UV_TOOL_BIN_DIR=<new private release>/bin",
                *command,
            ]
            print(f"Install command: {shlex.join(isolated)}", file=self.stdout)
            print(
                "Publication: verify the candidate, then atomically switch the launcher; retain releases used by running commands.",
                file=self.stdout,
            )
            print(
                f"Dry run: confirmed Yoke {version} is published at "
                f"{_safe_url(self.options.base_url)}. "
                "No package was installed and no configuration was written. "
                "Publication does not prove dependencies, wheel integrity, or "
                "that installation would succeed.",
                file=self.stdout,
            )
            return
        print(self._say("Setting up Yoke…"), file=self.stdout)
        config_path = self._write_uv_index_config()
        try:
            already = self._run_uv_install(
                self.install_command(spec, config_path=config_path)
            )
        finally:
            os.unlink(config_path)
        yoke_bin = self._resolve_installed_yoke_bin()
        shell_update = self.capture_runner([yoke_bin, "path", "fix", "--yes", "--json"])
        if shell_update.returncode:
            raise InstallError(
                "shell_path_setup_failed: "
                + (shell_update.stderr or shell_update.stdout).strip()
                + f"; run {shlex.quote(yoke_bin)} path fix --yes, then rerun the installer."
            )
        installed_version = self._smoke_yoke(yoke_bin)
        display = _display_version(installed_version)
        # Readiness comes only after every required check passes: a
        # product-boundary or credential-helper repair failure must never
        # print a "ready" screen before raising.
        self._product_boundary_audit(expected_version=version, yoke_bin=yoke_bin)
        self._repair_credential_helper(yoke_bin)
        self._record_distribution(yoke_bin)
        argv = [yoke_bin, "hook", "resident", "restart"]
        resident = self.capture_runner(argv)
        if resident.returncode:
            raise InstallError(
                "hook_evaluator_readiness_failed: the installed evaluator did not "
                "pass its readiness check. "
                + _bounded_diagnostic(
                    (resident.stdout or "") + "\n" + (resident.stderr or ""),
                    DIAGNOSTIC_MAX_CHARS,
                )
                + "; run yoke hook resident restart, then retry the installer."
            )
        self._restart_running_dashboard(yoke_bin)
        try:
            wsl_setup = self.terminal_runner([yoke_bin, "wsl", "setup"])
        except OSError as exc:
            raise InstallError(
                f"wsl_systemd_setup_unavailable: {exc}. "
                "Rerun the installer to repair the installed yoke executable."
            ) from exc
        if wsl_setup.returncode:
            raise InstallError(
                "wsl_systemd_setup_failed: See the WSL setup reason above. "
                "Rerun yoke wsl setup in an Ubuntu terminal with administrator access, "
                "then rerun the installer."
            )
        if already:
            print(self._say(f"Yoke v{display} already installed"), file=self.stdout)
        else:
            print(self._say(f"Yoke v{display} is ready"), file=self.stdout)
        self._advise_path(yoke_bin)


if __name__ == "__main__":
    raise SystemExit(main())
